window.__finlexDocLoaded(10131,{"id":10131,"articles":[{"id":1000569,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"IFRIC 21 clarifies when an entity recognises a liability for levies imposed by a government other than specified levies such as income taxes, fines and penalties. Applying IFRIC 21, an entity recognises a liability when it conducts the activity that triggers the payment of a levy under law or regulation. A liability is recognised progressively if the obligating event occurs over a period of time. If an obligation is triggered on reaching a minimum threshold, the liability is recognised when that minimum threshold is reached.","seq":0},{"id":1000570,"no":"IFRIC 21.8–14","heading":"Levies: Obligating Event Recognition","text":"Recognise a liability for a government levy ONLY when the activity triggering payment (as identified by legislation) occurs; do NOT accrue progressively before a minimum threshold is reached.","seq":1},{"id":1000571,"no":"History","heading":"Standard History & Amendments","text":"In May 2013 the International Accounting Standards Board issued IFRIC 21 Levies. It was developed by the Interpretations Committee.","seq":2},{"id":1000572,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related active projects]\n• Provisions—Targeted Improvements\n\n[Related completed projects]\n• Levies\n\n[Related IFRS Standards]\n• IAS 37 Provisions, Contingent Liabilities and Contingent Assets","seq":3},{"id":1000573,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/ifric-21-levies/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":4}]});
